const HOUR_MS = 60 * 60 * 1000;

function buildCommand() {
  const __args = [['work'], 'Economy', 'Work to earn money', async ({ sock, from, msg, senderNumber, db }) => {
  const e = db.econ(senderNumber);
  if (Date.now() - e.lastWork < HOUR_MS) {
    const mins = Math.ceil((HOUR_MS - (Date.now() - e.lastWork)) / 60000);
    return sock.sendMessage(from, { text: `⏳ Still tired. Try again in ${mins}m.` }, { quoted: msg });
  }
  const earned = Math.floor(Math.random() * 100) + 50;
  e.balance += earned;
  e.lastWork = Date.now();
  db.saveEcon();
  await sock.sendMessage(from, { text: `💼 You worked and earned ${earned}. Wallet: ${e.balance}` }, { quoted: msg });
}];
  const [commandsArr, section, description, handler, opts = {}] = __args;
  return { commands: commandsArr, section, description, handler, ownerOnly: !!opts.ownerOnly };
}

module.exports = buildCommand();
